package com.model;

import static org.junit.Assert.*;

import java.util.UUID;

import org.junit.Before;
import org.junit.Test;

/**
 * Tests for Shelter: hasType, addOccupants (plus the overlapping addOccupant and
 * addOccupantGroup), restock, and addResource.
 *
 * Tested by: Jake McNulty
 * AI use: first draft of test cases and comments generated by Ai and then checkover and rewritten by Jake McNulty
 *
+--------------------------------------------+--------------------------------------------------------------------+
| Test                                       | Reasoning                                                          |
+--------------------------------------------+--------------------------------------------------------------------+
| hasType: has type / lacks type             | -basic yes/no check used by the shelter search                     |
| hasType: no types / null                   | -should return false, not crash                                    |
+--------------------------------------------+--------------------------------------------------------------------+
| addOccupants: room for everyone            | -occupancy and pet count go up by the group size                   |
| addOccupants: exactly fills shelter        | -the last open spots can be used                                   |
| addOccupants: too many people / pets       | -nobody is checked in if the whole group doesn't fit               |
| addOccupants: no pet capacity              | -a group with a pet can't check into a no-pet shelter              |
| addOccupants: negative numbers             | -checking in can never lower occupancy                             |
| addOccupant: open / full shelter           | -single check-in respects capacity                                 |
| addOccupantGroup: room / exactly fills     | -should accept the same groups addOccupants does                   |
+--------------------------------------------+--------------------------------------------------------------------+
| restock: existing type                     | -adds to the amount without making a second entry                  |
| restock: new type                          | -creates the resource with the given amount                        |
| restock: other resources                   | -restocking one type leaves the rest alone                         |
| restock: negative amount / null type       | -can't lower stock or add a resource with no type                  |
+--------------------------------------------+--------------------------------------------------------------------+
| addResource: new type                      | -adds the resource with its amount                                 |
| addResource: shelter with no resources     | -works on a shelter created with a null list                       |
| addResource: type shelter already has      | -should merge into one entry, like restock does                    |
| addResource: null                          | -should be ignored                                                 |
+--------------------------------------------+--------------------------------------------------------------------+
 */

public class ShelterTest {
    
    private Shelter riverside;
    private Shelter small;

    @Before
    public void setUp() {
        riverside = TestFixtures.riverside();
        small = new Shelter("Small Church Hall", true, null, TestFixtures.riversideAddress(),
                TestFixtures.shelterTypes(ShelterType.PET_FRIENDLY), 8, 10, UUID.randomUUID(), 2, 1);
    }

    // quantity of given resource or 0 if shelter has none
    private int quantityOf(Shelter shelter, ResourceType type) {
        for (Resource resource : shelter.getResources()) {
            if (resource != null && resource.getResourceType() == type) {
                return resource.getQuantity();
            }
        }
        return 0;
    }

    // How many separate entries of the given resource the shelter has. */
    private int entriesOf(Shelter shelter, ResourceType type) {
        int count = 0;
        for (Resource resource : shelter.getResources()) {
            if (resource != null && resource.getResourceType() == type)
                count++;
        }
        return count;
    }

    // -- hasType

    @Test
    public void hasType_typeTheShelterHas_returnsTrue() {
        assertTrue(riverside.hasType(ShelterType.MEDICAL_STAFF));
    }

    @Test
    public void hasType_typeTheShelterLacks_returnsFalse() {
        assertFalse(riverside.hasType(ShelterType.SCHOOL));
    }

    @Test
    public void hasType_shelterCreatedWithNullTypes_returnsFalse() {
        Shelter noTypes = new Shelter("No Types", true, null, TestFixtures.riversideAddress(), null, 0, 50,
                UUID.randomUUID());
        assertFalse(noTypes.hasType(ShelterType.PET_FRIENDLY));
    }

    @Test
    public void hasType_nullType_returnsFalse() {
        assertFalse(riverside.hasType(null));
    }

    // -- addOccupants(people, pets)

    @Test
    public void addOccupants_roomForEveryone_increasesOccupancy() {
        riverside.addOccupants(3, 1);
        assertEquals(143, riverside.getOccupancy());
    }

    @Test
    public void addOccupants_roomForEveryone_increasesPetCount() {
        riverside.addOccupants(3, 1);
        assertEquals(1, riverside.getPetCount());
    }

    @Test
    public void addOccupants_groupExactlyFillsShelter_isAccepted() {
        small.addOccupants(2, 1);
        assertEquals(10, small.getOccupancy());
    }

    @Test
    public void addOccupants_tooManyPeople_leavesOccupancyUnchanged() {
        small.addOccupants(3, 0);
        assertEquals(8, small.getOccupancy());
    }

    @Test
    public void addOccupants_tooManyPets_leavesOccupancyUnchanged() {
        small.addOccupants(1, 2);
        assertEquals(8, small.getOccupancy());
    }

    @Test
    public void addOccupants_tooManyPets_leavesPetCountUnchanged() {
        small.addOccupants(1, 2);
        assertEquals(1, small.getPetCount());
    }

    @Test
    public void addOccupants_shelterWithNoPetCapacity_rejectsGroupWithPet() {
        Shelter noPets = new Shelter("No Pets", true, null, TestFixtures.riversideAddress(), null, 0, 50,
                UUID.randomUUID());
        noPets.addOccupants(2, 1);
        assertEquals(0, noPets.getOccupancy());
    }

    @Test
    public void addOccupants_negativePeople_leavesOccupancyUnchanged() {
        riverside.addOccupants(-5, 0);
        assertEquals(140, riverside.getOccupancy());
    }

    @Test
    public void addOccupants_negativePets_leavesPetCountUnchanged() {
        small.addOccupants(0, -1);
        assertEquals(1, small.getPetCount());
    }

    // -- the overlapping methods: addOccupant() and addOccupantGroup(size)

    @Test
    public void addOccupant_openShelter_increasesOccupancyByOne() {
        riverside.addOccupant();
        assertEquals(141, riverside.getOccupancy());
    }

    @Test
    public void addOccupant_fullShelter_leavesOccupancyUnchanged() {
        small.addOccupants(2, 0); // now 10 / 10
        small.addOccupant();
        assertEquals(10, small.getOccupancy());
    }

    @Test
    public void addOccupantGroup_roomForGroup_increasesOccupancy() {
        riverside.addOccupantGroup(3);
        assertEquals(143, riverside.getOccupancy());
    }

    @Test
    public void addOccupantGroup_groupExactlyFillsShelter_isAccepted() {
        // addOccupants(2, 0) accepts this same group, so addOccupantGroup(2) should too
        small.addOccupantGroup(2);
        assertEquals(10, small.getOccupancy());
    }

    // -- restock

    @Test
    public void restock_existingType_addsToQuantity() {
        riverside.restock(ResourceType.WATER, 8);
        assertEquals(20, quantityOf(riverside, ResourceType.WATER));
    }

    @Test
    public void restock_existingType_doesNotCreateSecondEntry() {
        riverside.restock(ResourceType.WATER, 8);
        assertEquals(1, entriesOf(riverside, ResourceType.WATER));
    }

    @Test
    public void restock_newType_addsResourceWithGivenQuantity() {
        riverside.restock(ResourceType.BLANKETS, 15);
        assertEquals(15, quantityOf(riverside, ResourceType.BLANKETS));
    }

    @Test
    public void restock_oneType_leavesOtherResourcesUnchanged() {
        riverside.restock(ResourceType.WATER, 8);
        assertEquals(8, quantityOf(riverside, ResourceType.FOOD));
    }

    @Test
    public void restock_negativeQuantity_leavesQuantityUnchanged() {
        riverside.restock(ResourceType.WATER, -20);
        assertEquals(12, quantityOf(riverside, ResourceType.WATER));
    }

    @Test
    public void restock_nullType_isIgnored() {
        riverside.restock(null, 5);
        assertEquals(2, riverside.getResources().size());
    }

    // -- addResource

    @Test
    public void addResource_newType_increasesResourceListSize() {
        riverside.addResource(new Resource(ResourceType.BLANKETS, 15));
        assertEquals(3, riverside.getResources().size());
    }

    @Test
    public void addResource_newType_keepsGivenQuantity() {
        riverside.addResource(new Resource(ResourceType.BLANKETS, 15));
        assertEquals(15, quantityOf(riverside, ResourceType.BLANKETS));
    }

    @Test
    public void addResource_shelterCreatedWithNullResources_addsResource() {
        small.addResource(new Resource(ResourceType.WATER, 4));
        assertEquals(4, quantityOf(small, ResourceType.WATER));
    }

    @Test
    public void addResource_typeShelterAlreadyHas_mergesIntoOneEntry() {
        riverside.addResource(new Resource(ResourceType.WATER, 5));
        assertEquals(1, entriesOf(riverside, ResourceType.WATER));
    }

    @Test
    public void addResource_nullResource_isIgnored() {
        riverside.addResource(null);
        assertEquals(2, riverside.getResources().size());
    }
}
